import struct

HEADER = struct.Struct("<4sI4s4sIHHIIHH4sI")


def read_wav_header(data):
    if len(data) < HEADER.size:
        raise ValueError("too short for a WAV header")
    (riff, _size, wave, fmt, fmt_size, audio_format, channels, rate,
     per_second, _align, bits, data_mark, data_size) = HEADER.unpack_from(data)
    if riff != b"RIFF" or wave != b"WAVE" or fmt != b"fmt " or data_mark != b"data" or fmt_size != 16:
        raise ValueError("not a plain WAV file")
    if audio_format != 1:
        raise ValueError("only PCM audio is supported")
    if per_second != rate * channels * bits // 8:
        raise ValueError("inconsistent header")
    return {"channels": channels, "sample_rate": rate, "bits": bits, "data_size": data_size,
            "seconds": round(data_size / per_second, 3)}

