import struct

def header(channels=2, rate=44100, bits=16, data_size=176400, fmt=1, per_second=None, mark=b"WAVE"):
    if per_second is None:
        per_second = rate * channels * bits // 8
    return struct.pack("<4sI4s4sIHHIIHH4sI", b"RIFF", 36 + data_size, mark, b"fmt ", 16, fmt, channels, rate,
                       per_second, channels * bits // 8, bits, b"data", data_size)

@test("reads a CD-quality header")
def _():
    check_eq(read_wav_header(header()), {"channels": 2, "sample_rate": 44100, "bits": 16,
                                          "data_size": 176400, "seconds": 1.0})

@test("works with extra sound data after the header")
def _():
    h = read_wav_header(header(channels=1, rate=8000, bits=8, data_size=12000) + bytes(12000))
    check_eq((h["channels"], h["seconds"]), (1, 1.5))

@test("refuses broken headers")
def _():
    check_raises(ValueError, read_wav_header, header()[:40])
    check_raises(ValueError, read_wav_header, header(mark=b"AVI "))
    check_raises(ValueError, read_wav_header, header(fmt=3))
    check_raises(ValueError, read_wav_header, header(per_second=1))

